/* Klepa Up: каталог. Новые NFT, номера 6 стран, коллекционные юзернеймы */
window.kupCatalog=function(c){
'use strict';
const {G,N,numImg}=c,IMG={"notebook": "", "wine": "", "frog": "", "mafia": "", "monkey": "", "cigarb": "", "cigarw": ""};
const NN=(n,ton,k)=>N(n,ton,'data:image/webp;base64,'+IMG[k]);
Object.assign(G,{notebook:NN('Star Notebook',7.8,'notebook'),wine:NN('Spiced Wine',9.6,'wine'),frog:NN('Shadow Pepe',5200,'frog'),cigarb:NN('Black Cigar',20.4,'cigarb'),cigarw:NN('White Cigar',27.5,'cigarw'),mafia:NN('Mafia Bear',58,'mafia'),monkey:NN('Nightmare Monkey',135,'monkey')});
/* ---------- номера стран ---------- */
const hash=s=>[...s].reduce((a,ch)=>Math.imul(a^ch.charCodeAt(0),16777619)>>>0,2166136261);
const rng=s=>()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296};
const CT=[{id:'ru',n:'Россия',cc:'+7',len:10,pre:'9',m:1,c:['#ff5468','#2a55e8']},{id:'ua',n:'Украина',cc:'+380',len:9,pre:'',m:.9,c:['#ffd21f','#2a6bff']},{id:'by',n:'Беларусь',cc:'+375',len:9,pre:'',m:.8,c:['#ff4d5e','#1f9d55']},{id:'fr',n:'Франция',cc:'+33',len:9,pre:'6',m:1.3,c:['#3d6bff','#ff4d6a']},{id:'us',n:'США',cc:'+1',len:10,pre:'',m:1.5,c:['#ff4d5e','#2a3fa8']},{id:'jp',n:'Япония',cc:'+81',len:10,pre:'90',m:1.4,c:['#ff6b7d','#b5133d']}];
const TN=[['Обычный',1200],['Стильный',6000],['Редкий',30000],['Эпичный',160000],['Легендарный',900000]];
const FM={ru:d=>`+7 ${d.slice(0,3)} ${d.slice(3,6)}-${d.slice(6,8)}-${d.slice(8)}`,ua:d=>`+380 ${d.slice(0,2)} ${d.slice(2,5)}-${d.slice(5,7)}-${d.slice(7)}`,by:d=>`+375 ${d.slice(0,2)} ${d.slice(2,5)}-${d.slice(5,7)}-${d.slice(7)}`,fr:d=>`+33 ${d[0]} ${d.slice(1,3)} ${d.slice(3,5)} ${d.slice(5,7)} ${d.slice(7)}`,us:d=>`+1 (${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}`,jp:d=>`+81 ${d.slice(0,2)}-${d.slice(2,6)}-${d.slice(6)}`};
const body=(t,L,r)=>{const d=()=>String(Math.floor(r()*10)),rn=n=>Array.from({length:n},d).join('');let s;
 if(t===1)s=rn(L);else if(t===2){s=(d()+d()).repeat(Math.ceil(L/2))}
 else if(t===3){const a=Math.floor(r()*4),up=r()<.5;s=Array.from({length:6},(_,i)=>String(up?a+i:9-a-i)).join('')+rn(Math.max(0,L-6))}
 else if(t===4){s=d().repeat(5)+rn(Math.max(0,L-5))}
 else{const a=d(),m=Math.floor(r()*3);s=m===0?a.repeat(L):m===1?a+'0'.repeat(L-1):a.repeat(L-3)+'000'}
 return s.slice(0,L).padEnd(L,'0')};
const NUMS={};
for(const ct of CT){NUMS[ct.id]={};for(let t=1;t<=5;t++){const r=rng(hash(ct.id+t)),set=new Set(),L=ct.len-ct.pre.length;let g=0;while(set.size<12&&g++<500)set.add(ct.pre+body(t,L,r));
 NUMS[ct.id][t]=[...set].map(d=>FM[ct.id](d));const price=Math.round(TN[t-1][1]*ct.m/100)*100;
 G['c'+ct.id+t]={n:ct.n+' · '+TN[t-1][0]+' номер',short:ct.cc,v:Math.round(price*.85),nft:1,num:1,cn:ct.id,tier:100+t,price,img:numImg(ct.c[0],ct.c[1],ct.cc)}}}
/* ---------- коллекционные юзернеймы ---------- */
const UT=[['Мифический',2100000,['#ffd21f','#ff3d00']],['Легендарный',380000,['#ff7ae6','#7b2cff']],['Эпический',74000,['#3bd6ff','#1747c9']],['Редкий',11000,['#6bffb0','#0b8a5a']],['Обычный',1400,['#c3c9ff','#4a52c9']]];
const AD=['gold','dark','neon','ice','fire','red','blue','lucky','wild','cyber','royal','mega'],NO=['king','wolf','fox','star','boss','hero','rider','lord','ninja','queen','tiger','eagle'],W3=[],W4=[],W5=[];
for(const a of AD)for(const n of NO)W3.push(a+n);for(const n of NO)for(const s of ['7','77','777','88','99','2026','_01'])W4.push(n+s);
for(const a of ['happy','lazy','tiny','brave','calm','cool','fast','wise','sunny','night'])for(const n of ['cat','fox','bear','owl','duck','frog','wolf','mouse','panda','koala'])W5.push(a+'_'+n);
const USR={1:'ace god king boss gold rich vip neo one top pro lux zen max win dev bit ton fox wolf lion luck cash coin hero cool star moon sun sky'.split(' '),2:'alpha omega royal crown tiger eagle shark viper cobra dragon ninja legend master wizard rocket planet galaxy cosmos matrix phoenix falcon spartan knight pirate hunter ghost shadow thunder storm blaze frost titan'.split(' '),3:W3.filter((_,i)=>i%2===0).slice(0,60),4:W4.slice(0,64),5:W5};
const usrImg=(c1,c2)=>'data:image/svg+xml;base64,'+btoa(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256"><defs><linearGradient id="a" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c1}"/><stop offset="1" stop-color="${c2}"/></linearGradient></defs><rect x="14" y="14" width="228" height="228" rx="60" fill="url(#a)"/><rect x="14" y="14" width="228" height="112" rx="60" fill="#fff" opacity=".13"/><text x="128" y="170" text-anchor="middle" font-family="Arial,Helvetica,sans-serif" font-weight="800" font-size="150" fill="#fff">@</text></svg>`);
UT.forEach((u,i)=>{G['usr'+(i+1)]={n:'Юзернейм · '+u[0],short:'@',v:Math.round(u[1]*.85),nft:1,usr:1,tier:201+i,price:u[1],img:usrImg(u[2][0],u[2][1])}});
/* ---------- флаги (SVG) ---------- */
const F=(b)=>`<svg class="fl" viewBox="0 0 24 16" aria-hidden="true"><clipPath id="fc"><rect width="24" height="16" rx="3"/></clipPath><g clip-path="url(#fc)">${b}</g></svg>`;
const FLAG={ru:F('<rect width="24" height="16" fill="#fff"/><rect y="5.33" width="24" height="5.34" fill="#2a55e8"/><rect y="10.67" width="24" height="5.33" fill="#e8334a"/>'),ua:F('<rect width="24" height="8" fill="#2a6bff"/><rect y="8" width="24" height="8" fill="#ffd21f"/>'),by:F('<rect width="24" height="16" fill="#e8334a"/><rect y="10.7" width="24" height="5.3" fill="#1f9d55"/><rect width="3.6" height="16" fill="#fff"/><path d="M1.8 1.6l1 1.6-1 1.6-1-1.6zm0 4l1 1.6-1 1.6-1-1.6zm0 4l1 1.6-1 1.6-1-1.6z" fill="#e8334a"/>'),fr:F('<rect width="8" height="16" fill="#2a55e8"/><rect x="8" width="8" height="16" fill="#fff"/><rect x="16" width="8" height="16" fill="#e8334a"/>'),us:F('<rect width="24" height="16" fill="#fff"/>'+[0,2,4,6,8,10,12].map(i=>`<rect y="${i*16/13}" width="24" height="${16/13}" fill="#e8334a"/>`).join('')+'<rect width="10.5" height="8.6" fill="#2a3fa8"/>'),jp:F('<rect width="24" height="16" fill="#fff"/><circle cx="12" cy="8" r="4.4" fill="#e8334a"/>'),sn:F('<rect width="24" height="16" fill="#3b7bff"/><rect x="3" y="3" width="18" height="10" rx="2" fill="#fff" opacity=".9"/><text x="12" y="11.2" text-anchor="middle" font-family="Arial" font-weight="800" font-size="6.5" fill="#1747c9">888</text>')};
window.KC={CT,TN,NUMS,UT,USR,FLAG,CTN:Object.fromEntries(CT.map(x=>[x.id,x.n])),
 genUsr(k,S){const t=G[k].tier-200,have=new Set((S.inv||[]).map(x=>x.un).filter(Boolean).concat((S.pnum||[]).filter(Boolean))),pool=USR[t].filter(n=>!have.has(n));if(pool.length)return pool[Math.random()*pool.length|0];let n,i=0;do{n=USR[t][Math.random()*USR[t].length|0]+(10+Math.random()*90|0)}while(have.has(n)&&i++<30);return n},
 numPrice:(id,t)=>G['c'+id+t].price,usrPrice:t=>UT[t-1][1]};
};
